-- Server-only transactional operations for chat, decks, battles and missions.
create or replace function public.server_get_or_create_conversation(p_actor_id uuid,p_friend_id uuid) returns uuid language plpgsql security definer set search_path=public as $$
declare v_a uuid;v_b uuid;v_id uuid;begin if p_actor_id=p_friend_id then raise exception 'INVALID_PLAYER';end if;if not exists(select 1 from friendships f where f.status::text='accepted' and ((f.requester_id=p_actor_id and f.addressee_id=p_friend_id) or (f.requester_id=p_friend_id and f.addressee_id=p_actor_id))) then raise exception 'NOT_FRIENDS';end if;if p_actor_id::text<p_friend_id::text then v_a:=p_actor_id;v_b:=p_friend_id;else v_a:=p_friend_id;v_b:=p_actor_id;end if;insert into conversations(player_a,player_b) values(v_a,v_b) on conflict(player_a,player_b) do update set updated_at=now() returning id into v_id;return v_id;end$$;

create or replace function public.server_send_message(p_actor_id uuid,p_conversation_id uuid,p_body text,p_kind text default 'text',p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid;v_other uuid;begin p_body:=btrim(coalesce(p_body,''));if char_length(p_body)<1 or char_length(p_body)>1000 then raise exception 'INVALID_MESSAGE';end if;if p_kind not in('text','battle_invite','battle_event','system') then raise exception 'INVALID_KIND';end if;select case when player_a=p_actor_id then player_b when player_b=p_actor_id then player_a else null end into v_other from conversations where id=p_conversation_id;if v_other is null then raise exception 'FORBIDDEN';end if;if not exists(select 1 from friendships f where f.status::text='accepted' and ((f.requester_id=p_actor_id and f.addressee_id=v_other) or (f.requester_id=v_other and f.addressee_id=p_actor_id))) then raise exception 'NOT_FRIENDS';end if;insert into messages(conversation_id,sender_id,body,kind,metadata) values(p_conversation_id,p_actor_id,p_body,p_kind,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;update conversations set updated_at=now() where id=p_conversation_id;return v_id;end$$;

create or replace function public.server_mark_conversation_read(p_actor_id uuid,p_conversation_id uuid) returns integer language plpgsql security definer set search_path=public as $$
declare v_count integer;begin if not exists(select 1 from conversations where id=p_conversation_id and p_actor_id in(player_a,player_b)) then raise exception 'FORBIDDEN';end if;update messages set read_at=now() where conversation_id=p_conversation_id and sender_id<>p_actor_id and read_at is null;get diagnostics v_count=row_count;return v_count;end$$;

create or replace function public.server_create_deck(p_player_id uuid,p_name text) returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid;begin p_name:=btrim(coalesce(p_name,''));if char_length(p_name)<1 or char_length(p_name)>40 then raise exception 'INVALID_NAME';end if;insert into decks(player_id,name,is_default) values(p_player_id,p_name,not exists(select 1 from decks where player_id=p_player_id)) returning id into v_id;return v_id;end$$;

create or replace function public.server_set_deck_cards(p_player_id uuid,p_deck_id uuid,p_cards jsonb) returns integer language plpgsql security definer set search_path=public as $$
declare v_item jsonb;v_card text;v_qty integer;v_owned integer;v_count integer:=0;begin if not exists(select 1 from decks where id=p_deck_id and player_id=p_player_id) then raise exception 'DECK_NOT_FOUND';end if;if jsonb_typeof(p_cards)<>'array' then raise exception 'INVALID_CARDS';end if;delete from deck_cards where deck_id=p_deck_id;for v_item in select * from jsonb_array_elements(p_cards) loop v_card:=v_item->>'card_id';v_qty:=coalesce((v_item->>'quantity')::integer,1);if v_qty<1 or v_qty>4 then raise exception 'INVALID_QUANTITY';end if;select quantity into v_owned from player_cards where player_id=p_player_id and card_id=v_card;if coalesce(v_owned,0)<v_qty then raise exception 'NOT_OWNED';end if;insert into deck_cards(deck_id,card_id,quantity) values(p_deck_id,v_card,v_qty);v_count:=v_count+v_qty;end loop;if v_count>20 then raise exception 'DECK_TOO_LARGE';end if;update decks set updated_at=now() where id=p_deck_id;return v_count;end$$;

create or replace function public.server_set_default_deck(p_player_id uuid,p_deck_id uuid) returns boolean language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from decks where id=p_deck_id and player_id=p_player_id) then raise exception 'DECK_NOT_FOUND';end if;update decks set is_default=false where player_id=p_player_id and is_default;update decks set is_default=true,updated_at=now() where id=p_deck_id;return true;end$$;

create or replace function public.server_create_battle(p_actor_id uuid,p_opponent_id uuid,p_mode text,p_stake_type text,p_wager_coins bigint) returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid;v_rounds integer;begin if p_actor_id=p_opponent_id then raise exception 'INVALID_PLAYER';end if;if p_mode not in('quick','mystery') then raise exception 'INVALID_MODE';end if;if p_stake_type not in('none','coins') then raise exception 'STAKE_NOT_AVAILABLE';end if;if p_stake_type='none' then p_wager_coins:=0;end if;if p_stake_type='coins' and(p_wager_coins<100 or p_wager_coins>5000) then raise exception 'INVALID_WAGER';end if;if not exists(select 1 from friendships f where f.status::text='accepted' and ((f.requester_id=p_actor_id and f.addressee_id=p_opponent_id) or (f.requester_id=p_opponent_id and f.addressee_id=p_actor_id))) then raise exception 'NOT_FRIENDS';end if;if p_stake_type='coins' and ((select coins from players where id=p_actor_id)<p_wager_coins or (select coins from players where id=p_opponent_id)<p_wager_coins) then raise exception 'NOT_ENOUGH_COINS';end if;v_rounds:=case when p_mode='mystery' then 2 else 1 end;insert into battles(challenger_id,opponent_id,mode,stake_type,wager_coins,rounds_to_win) values(p_actor_id,p_opponent_id,p_mode,p_stake_type,p_wager_coins,v_rounds) returning id into v_id;insert into battle_events(battle_id,event_type,payload) values(v_id,'invited',jsonb_build_object('challengerId',p_actor_id,'opponentId',p_opponent_id,'mode',p_mode,'stakeType',p_stake_type,'wagerCoins',p_wager_coins));return v_id;end$$;

create or replace function public.server_respond_battle(p_actor_id uuid,p_battle_id uuid,p_accept boolean) returns jsonb language plpgsql security definer set search_path=public as $$
declare b battles%rowtype;c_coins bigint;o_coins bigint;begin select * into b from battles where id=p_battle_id for update;if b.id is null then raise exception 'BATTLE_NOT_FOUND';end if;if b.opponent_id<>p_actor_id then raise exception 'FORBIDDEN';end if;if b.status<>'invited' then raise exception 'INVALID_STATUS';end if;if not p_accept then update battles set status='declined',updated_at=now() where id=b.id;insert into battle_events(battle_id,event_type,payload) values(b.id,'declined','{}');return jsonb_build_object('status','declined');end if;if b.stake_type='coins' then select coins into c_coins from players where id=b.challenger_id for update;select coins into o_coins from players where id=b.opponent_id for update;if c_coins<b.wager_coins or o_coins<b.wager_coins then raise exception 'NOT_ENOUGH_COINS';end if;update players set coins=coins-b.wager_coins where id in(b.challenger_id,b.opponent_id);insert into battle_coin_escrows(battle_id,player_id,amount,status) values(b.id,b.challenger_id,b.wager_coins,'held'),(b.id,b.opponent_id,b.wager_coins,'held') on conflict(battle_id,player_id) do nothing;end if;update battles set status='selecting',selection_deadline=now()+make_interval(secs=>selection_seconds),updated_at=now() where id=b.id;insert into battle_events(battle_id,event_type,payload) values(b.id,'started',jsonb_build_object('round',1,'selectionSeconds',b.selection_seconds));return jsonb_build_object('status','selecting','round',1,'selectionSeconds',b.selection_seconds);end$$;

create or replace function public.server_lock_battle_card(p_actor_id uuid,p_battle_id uuid,p_card_id text) returns jsonb language plpgsql security definer set search_path=public as $$
declare b battles%rowtype;v_count integer;begin select * into b from battles where id=p_battle_id for update;if b.id is null then raise exception 'BATTLE_NOT_FOUND';end if;if p_actor_id not in(b.challenger_id,b.opponent_id) then raise exception 'FORBIDDEN';end if;if b.status<>'selecting' then raise exception 'INVALID_STATUS';end if;if b.selection_deadline is not null and now()>b.selection_deadline then raise exception 'SELECTION_EXPIRED';end if;if not exists(select 1 from player_cards where player_id=p_actor_id and card_id=p_card_id and quantity>0) then raise exception 'NOT_OWNED';end if;if exists(select 1 from battle_selections where battle_id=b.id and round_no=b.active_round and player_id=p_actor_id) then raise exception 'ALREADY_LOCKED';end if;insert into battle_selections(battle_id,round_no,player_id,card_id) values(b.id,b.active_round,p_actor_id,p_card_id);select count(*) into v_count from battle_selections where battle_id=b.id and round_no=b.active_round;insert into battle_events(battle_id,event_type,payload) values(b.id,'card_locked',jsonb_build_object('playerId',p_actor_id,'round',b.active_round));return jsonb_build_object('locked',true,'bothLocked',v_count=2,'round',b.active_round);end$$;

create or replace function public.server_finish_battle_round(p_battle_id uuid,p_round_no integer,p_challenger_power numeric,p_opponent_power numeric,p_challenger_roll numeric,p_opponent_roll numeric,p_winner_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare b battles%rowtype;c_card text;o_card text;c_score integer;o_score integer;v_complete boolean;v_winner uuid;v_pot bigint;begin select * into b from battles where id=p_battle_id for update;if b.id is null then raise exception 'BATTLE_NOT_FOUND';end if;if b.status<>'selecting' or b.active_round<>p_round_no then raise exception 'INVALID_STATUS';end if;if p_winner_id not in(b.challenger_id,b.opponent_id) then raise exception 'INVALID_WINNER';end if;select card_id into c_card from battle_selections where battle_id=b.id and round_no=p_round_no and player_id=b.challenger_id;select card_id into o_card from battle_selections where battle_id=b.id and round_no=p_round_no and player_id=b.opponent_id;if c_card is null or o_card is null then raise exception 'SELECTIONS_MISSING';end if;if exists(select 1 from battle_rounds where battle_id=b.id and round_no=p_round_no) then raise exception 'ROUND_ALREADY_RESOLVED';end if;insert into battle_rounds(battle_id,round_no,challenger_card_id,opponent_card_id,challenger_power,opponent_power,challenger_roll,opponent_roll,winner_id) values(b.id,p_round_no,c_card,o_card,p_challenger_power,p_opponent_power,p_challenger_roll,p_opponent_roll,p_winner_id);c_score:=b.challenger_score+case when p_winner_id=b.challenger_id then 1 else 0 end;o_score:=b.opponent_score+case when p_winner_id=b.opponent_id then 1 else 0 end;v_complete:=c_score>=b.rounds_to_win or o_score>=b.rounds_to_win;if v_complete then v_winner:=case when c_score>o_score then b.challenger_id else b.opponent_id end;update battles set challenger_score=c_score,opponent_score=o_score,status='completed',winner_id=v_winner,completed_at=now(),updated_at=now() where id=b.id;if b.stake_type='coins' then select coalesce(sum(amount),0) into v_pot from battle_coin_escrows where battle_id=b.id and status='held';if v_pot>0 then update players set coins=coins+v_pot where id=v_winner;update battle_coin_escrows set status='paid',updated_at=now() where battle_id=b.id and status='held';end if;end if;update players set xp=xp+case when id=v_winner then 50 else 20 end,level=greatest(level,1+floor((xp+case when id=v_winner then 50 else 20 end)/250.0)::integer) where id in(b.challenger_id,b.opponent_id);insert into player_daily_missions(player_id,mission_date,mission_id,progress) values(b.challenger_id,current_date,'play_2_battles',1),(b.opponent_id,current_date,'play_2_battles',1),(v_winner,current_date,'win_1_battle',1) on conflict(player_id,mission_date,mission_id) do update set progress=player_daily_missions.progress+excluded.progress,updated_at=now();insert into battle_events(battle_id,event_type,payload) values(b.id,'completed',jsonb_build_object('winnerId',v_winner,'challengerScore',c_score,'opponentScore',o_score));return jsonb_build_object('completed',true,'winnerId',v_winner,'challengerScore',c_score,'opponentScore',o_score);else update battles set challenger_score=c_score,opponent_score=o_score,active_round=active_round+1,selection_deadline=now()+make_interval(secs=>selection_seconds),updated_at=now() where id=b.id;insert into battle_events(battle_id,event_type,payload) values(b.id,'round_resolved',jsonb_build_object('round',p_round_no,'winnerId',p_winner_id,'challengerScore',c_score,'opponentScore',o_score));return jsonb_build_object('completed',false,'nextRound',p_round_no+1,'challengerScore',c_score,'opponentScore',o_score);end if;end$$;

create or replace function public.server_cancel_battle(p_actor_id uuid,p_battle_id uuid) returns text language plpgsql security definer set search_path=public as $$
declare b battles%rowtype;begin select * into b from battles where id=p_battle_id for update;if b.id is null then raise exception 'BATTLE_NOT_FOUND';end if;if p_actor_id not in(b.challenger_id,b.opponent_id) then raise exception 'FORBIDDEN';end if;if b.status not in('invited','selecting') then raise exception 'INVALID_STATUS';end if;if b.status='selecting' and exists(select 1 from battle_selections where battle_id=b.id) then raise exception 'BATTLE_ALREADY_STARTED';end if;if b.stake_type='coins' then update players p set coins=p.coins+e.amount from battle_coin_escrows e where e.battle_id=b.id and e.player_id=p.id and e.status='held';update battle_coin_escrows set status='refunded',updated_at=now() where battle_id=b.id and status='held';end if;update battles set status='cancelled',updated_at=now() where id=b.id;insert into battle_events(battle_id,event_type,payload) values(b.id,'cancelled',jsonb_build_object('by',p_actor_id));return 'cancelled';end$$;

create or replace function public.server_timeout_battle(p_actor_id uuid,p_battle_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare b battles%rowtype;v_card text;v_count integer;begin select * into b from battles where id=p_battle_id for update;if b.id is null then raise exception 'BATTLE_NOT_FOUND';end if;if p_actor_id not in(b.challenger_id,b.opponent_id) then raise exception 'FORBIDDEN';end if;if b.status<>'selecting' then raise exception 'INVALID_STATUS';end if;if b.selection_deadline is null or now()<b.selection_deadline then raise exception 'NOT_EXPIRED';end if;if not exists(select 1 from battle_selections where battle_id=b.id and round_no=b.active_round and player_id=b.challenger_id) then select card_id into v_card from player_cards where player_id=b.challenger_id and quantity>0 order by random() limit 1;if v_card is null then raise exception 'CHALLENGER_NO_CARDS';end if;insert into battle_selections(battle_id,round_no,player_id,card_id) values(b.id,b.active_round,b.challenger_id,v_card);insert into battle_events(battle_id,event_type,payload) values(b.id,'auto_locked',jsonb_build_object('playerId',b.challenger_id,'round',b.active_round));end if;if not exists(select 1 from battle_selections where battle_id=b.id and round_no=b.active_round and player_id=b.opponent_id) then select card_id into v_card from player_cards where player_id=b.opponent_id and quantity>0 order by random() limit 1;if v_card is null then raise exception 'OPPONENT_NO_CARDS';end if;insert into battle_selections(battle_id,round_no,player_id,card_id) values(b.id,b.active_round,b.opponent_id,v_card);insert into battle_events(battle_id,event_type,payload) values(b.id,'auto_locked',jsonb_build_object('playerId',b.opponent_id,'round',b.active_round));end if;select count(*) into v_count from battle_selections where battle_id=b.id and round_no=b.active_round;return jsonb_build_object('bothLocked',v_count=2,'round',b.active_round,'timedOut',true);end$$;

create or replace function public.server_claim_daily_mission(p_player_id uuid,p_mission_id text) returns jsonb language plpgsql security definer set search_path=public as $$
declare pm player_daily_missions%rowtype;mt mission_templates%rowtype;begin select * into mt from mission_templates where id=p_mission_id and active;if mt.id is null then raise exception 'MISSION_NOT_FOUND';end if;select * into pm from player_daily_missions where player_id=p_player_id and mission_date=current_date and mission_id=p_mission_id for update;if pm.mission_id is null or pm.progress<mt.target then raise exception 'MISSION_NOT_COMPLETE';end if;if pm.claimed then raise exception 'ALREADY_CLAIMED';end if;update player_daily_missions set claimed=true,updated_at=now() where player_id=p_player_id and mission_date=current_date and mission_id=p_mission_id;update players set coins=coins+mt.reward_coins,xp=xp+mt.reward_xp,level=greatest(level,1+floor((xp+mt.reward_xp)/250.0)::integer) where id=p_player_id;return jsonb_build_object('coins',mt.reward_coins,'xp',mt.reward_xp);end$$;

do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('server_get_or_create_conversation','server_send_message','server_mark_conversation_read','server_create_deck','server_set_deck_cards','server_set_default_deck','server_create_battle','server_respond_battle','server_lock_battle_card','server_finish_battle_round','server_cancel_battle','server_timeout_battle','server_claim_daily_mission') loop execute format('revoke all on function %s from public, anon, authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end$$;
